            return default
        d = {}
        try:
            d = obj.__dict__
        except Exception:
            d = {}
        for n in names:
            if n in d:
                return d[n]
        for n in names:
            try:
                return obj[n]
            except Exception:
                pass
        return default

    coords = pick(instance, ("coords", "coordinates", "locs", "points"), None)
    distmat = pick(instance, ("distance_matrix", "distances", "matrix"), None)
    demands = pick(instance, ("demands", "demand"), None)
    capacity = pick(instance, ("capacity", "vehicle_capacity", "cap"), None)
    depot = pick(instance, ("depot", "depot_id", "depot_index"), 0)

    if demands is None:
        demands = {}
    if isinstance(demands, list):
        dem_map = {i: demands[i] for i in range(len(demands))}
    else:
        try:
            dem_map = dict(demands)
        except Exception:
            dem_map = {}

    coord_map = None
    if isinstance(coords, list):
        coord_map = {i: coords[i] for i in range(len(coords))}
    elif isinstance(coords, dict):
        coord_map = dict(coords)

    all_ids = set(dem_map.keys())
    if coord_map is not None:
        all_ids |= set(coord_map.keys())
    if isinstance(distmat, list):
        all_ids |= set(range(len(distmat)))
    all_ids.discard(depot)
    customers = sorted(all_ids)

    def dist(a, b):
        if distmat is not None:
            try:
                return distmat[a][b]
            except Exception:
                pass
        if coord_map is not None:
            ax, ay = coord_map[a]
            bx, by = coord_map[b]
            dx = ax - bx
            dy = ay - by
            return (dx * dx + dy * dy) ** 0.5
        return 0 if a == b else 1

    def demand(c):
        return dem_map[c] if c in dem_map else 1

    if capacity is None:
        total = 0
        for c in customers:
            total += demand(c)
        capacity = total if total > 0 else 1

    def route_load(route):
        s = 0
        for c in route:
            s += demand(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        cost = dist(depot, route[0])
        for i in range(len(route) - 1):
            cost += dist(route[i], route[i + 1])
        cost += dist(route[-1], depot)
        return cost

    def route_order(route):
        if coord_map is None or len(route) < 3:
            return route[:]
        remaining = route[:]
        ordered = []
        if depot in coord_map:
            dx, dy = coord_map[depot]
        else:
            dx, dy = 0, 0
        start = min(remaining, key=lambda c: (dist(depot, c), c))
        ordered.append(start)
        remaining.remove(start)
        while remaining:
            last = ordered[-1]
            nxt = min(remaining, key=lambda c: (dist(last, c), dist(depot, c), c))
            ordered.append(nxt)
            remaining.remove(nxt)
        return ordered

    unassigned = set(customers)
    routes = []

    seeds = sorted(customers, key=lambda c: (dist(depot, c), demand(c), c), reverse=True)

    while unassigned:
        seed = None
        for c in seeds:
            if c in unassigned:
                seed = c
                break
        if seed is None:
            seed = min(unassigned)
        route = [seed]
        unassigned.remove(seed)
        load = demand(seed)

        while True:
            best = None
            best_key = None
            last = route[-1]
            for c in unassigned:
                dc = demand(c)
                if load + dc > capacity:
                    continue
                inc = dist(last, c) + dist(c, depot) - dist(last, depot)
                key = (inc, dist(seed, c), dc, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = c
            if best is None:
                break
            route.append(best)
            unassigned.remove(best)
            load += demand(best)

        route = route_order(route)
        routes.append(route)

    changed = True
    while changed:
        changed = False
        routes.sort(key=lambda r: (route_load(r), len(r), route_cost(r)))
        i = 0
        while i < len(routes):
            j = i + 1
            while j < len(routes):
                ri = routes[i]
                rj = routes[j]
                if route_load(ri) + route_load(rj) <= capacity:
                    merged = route_order(ri + rj)
                    if route_cost(merged) <= route_cost(ri) + route_cost(rj):
                        routes[i] = merged
                        del routes[j]
                        changed = True
                        break
                j += 1
            if changed:
                break
            i += 1

    def two_opt(route):
        best = route[:]
        best_cost = route_cost(best)
        n = len(route)
        improved = False
        for i in range(n - 1):
            for k in range(i + 1, n):
                cand = route[:i] + route[i:k + 1][::-1] + route[k + 1:]
                c = route_cost(cand)
                if c + 1e-12 < best_cost:
                    best = cand
                    best_cost = c
                    improved = True
        return best, improved

    improved = True
    while improved:
        improved = False
        for idx in range(len(routes)):
            nr, ch = two_opt(routes[idx])
            if ch:
                routes[idx] = nr
                improved = True

        best_move = None
        best_delta = 0
        for a in range(len(routes)):
            ra = routes[a]
            cost_a = route_cost(ra)
            load_a = route_load(ra)
            for pos_a, c in enumerate(ra):
                dc = demand(c)
                ra2 = ra[:pos_a] + ra[pos_a + 1:]
                cost_ra2 = route_cost(ra2) if ra2 else 0
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if route_load(rb) + dc > capacity:
                        continue
                    cost_b = route_cost(rb)
                    for pos_b in range(len(rb) + 1):
                        nb = rb[:pos_b] + [c] + rb[pos_b:]
                        delta = (cost_ra2 + route_cost(nb)) - (cost_a + cost_b)
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (a, b, pos_a, pos_b, c)
        if best_move is not None:
            a, b, pos_a, pos_b, c = best_move
            ra = routes[a]
            rb = routes[b]
            ra2 = ra[:pos_a] + ra[pos_a + 1:]
            rb2 = rb[:pos_b] + [c] + rb[pos_b:]
            if ra2:
                routes[a] = ra2
                if b > a:
                    b -= 1
                routes[b] = rb2
            else:
                del routes[a]
                if b > a:
                    b -= 1
                routes[b] = rb2
            improved = True

    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        for c in r:
            if c not in seen:
                seen.add(c)
                nr.append(c)
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        dc = demand(c)
        best_choice = None
        for i, r in enumerate(final_routes):
            if route_load(r) + dc <= capacity:
                for pos in range(len(r) + 1):
                    cand = r[:pos] + [c] + r[pos:]
                    key = (route_cost(cand) - route_cost(r), i, pos, c)
                    if best_choice is None or key < best_choice[0]:
                        best_choice = (key, i, cand)
        if best_choice is not None:
            _, i, cand = best_choice
            final_routes[i] = cand
            placed = True
        if not placed:
            final_routes.append([c])

    return final_routes
